from pathlib import Path
import json, html, re
P=Path(__file__).resolve().parent
D=json.loads((P/'data/research_financials.json').read_text())
V=json.loads((P/'valuation-results.json').read_text())
A=D['annual'];Q=D['quarter']; S=D['sources']
def esc(v):return html.escape(str(v))
def num(x):return f'{x:,.2f}' if isinstance(x,float) else f'{x:,}' if isinstance(x,int) else esc(x)
def pct(x):return f'{x*100:.2f}%'
def table(headers,rows):return '<div class="scroll"><table><thead><tr>'+''.join('<th>'+esc(x)+'</th>' for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+str(x)+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def source(key):return '<p class="source">来源：<a href="'+S[key]+'">Microsoft 官方原文</a>；取证 2026-11-15。金额均为百万美元，除非另注。</p>'
def section(i,title,body):return f'<section id="s{i}"><h2>{i}. {title}</h2>{body}</section>'
def bars():
 out=['<svg viewBox="0 0 760 260" role="img" aria-label="五年经营现金流与资本支出，从零起点，单位十亿美元">']
 for j,y in enumerate(D['years']):
  x=65+j*140
  for k,(f,c) in enumerate([('CFO','#187b83'),('cash_CapEx','#cf8055')]):
   h=A[f][j]/1000;out.append(f'<rect x="{x+k*42}" y="{220-h}" width="34" height="{h}" fill="{c}"/><text x="{x+k*42+17}" y="{212-h}" text-anchor="middle">{h:.1f}</text>')
  out.append(f'<text x="{x+36}" y="244" text-anchor="middle">FY{y}</text>')
 out.append('<line x1="40" y1="220" x2="740" y2="220" stroke="#667"/><text x="3" y="225">0</text></svg><p class="source">蓝绿：经营现金流；橙：现金资本开支。共同零基线、同一比例；精确底表如下。</p>')
 return ''.join(out)
def cash_bridge():
 vals=[182935,-115948,-26445,-22271,18271]; names=['经营现金流','现金CapEx','现金分红','现金表回购','剩余差额']
 out=['<svg viewBox="0 0 760 280" role="img" aria-label="FY26经营现金来源用途瀑布图，单位十亿美元">']; balance=0
 for i,(v,n) in enumerate(zip(vals,names)):
  if i in (0,4): lo,hi=0,v;balance=v
  else: hi=balance;balance+=v;lo=balance
  x=48+i*145;out.append(f'<rect x="{x}" y="{220-hi/1000}" width="102" height="{(hi-lo)/1000}" fill="'+('#187b83' if i in (0,4) else '#cf8055')+f'"/><text x="{x+51}" y="{211-hi/1000}" text-anchor="middle">{v/1000:+.3f}</text><text x="{x+51}" y="244" text-anchor="middle">{n}</text>')
  if i<4:out.append(f'<line x1="{x+102}" x2="{x+145}" y1="{220-balance/1000}" y2="{220-balance/1000}" stroke="#999"/>')
 out.append('<line x1="30" x2="750" y1="220" y2="220" stroke="#777"/><text x="5" y="224">0</text></svg>')
 return ''.join(out)
annual_rows=[]
labels={'revenue':'收入','gross_profit':'毛利','operating_income':'经营利润','net_income':'GAAP净利润','CFO':'经营现金流','cash_CapEx':'现金资本开支','FCF':'自由现金流','cash_and_short_investments':'现金及短期投资（期末）','cash_dividends':'现金分红','cash_repurchases':'现金流量表回购支出','RD':'研发费用'}
