for label,f in [('毛利率','gross_profit'),('经营利润率','operating_income'),('净利率','net_income'),('FCF利润率','FCF')]:annual_rows.append([label]+[pct(x/y) for x,y in zip(A[f],A['revenue'])])
annual_rows.append(['收入同比']+['17.96%（第三方）']+[pct(A['revenue'][i]/A['revenue'][i-1]-1) for i in range(1,5)])
annual_rows.append(['CapEx / CFO']+[pct(x/y) for x,y in zip(A['cash_CapEx'],A['CFO'])])
qrows=[]
for f,label in labels.items():
 if f in Q:
  x,y=Q[f];qrows.append([label,num(y),num(x),pct(x/y-1)])
for label,f in [('毛利率','gross_profit'),('经营利润率','operating_income'),('净利率','net_income')]:
 x,y=Q[f];rx,ry=Q['revenue'];qrows.append([label,pct(y/ry),pct(x/rx),f'{100*(x/rx-y/ry):+.2f}个百分点'])
