css='''body{font:16px/1.8 system-ui,-apple-system,"PingFang SC",sans-serif;color:#23343e;background:#f4f5f2;margin:0}main{max-width:1120px;margin:auto;padding:42px 30px}h1{font-size:34px;line-height:1.4}h2{font-size:25px;color:#165e67}h3{font-size:19px;margin-top:28px}section{background:white;padding:24px 30px;margin:22px 0;border:1px solid #dce2df;border-radius:12px}table{border-collapse:collapse;width:100%;font-size:14px}th,td{padding:10px 12px;border-bottom:1px solid #dde2df;text-align:right;vertical-align:top;min-width:90px}td:first-child,th:first-child{text-align:left;min-width:150px}thead{background:#eef4f2}.scroll{overflow-x:auto}a{color:#166d80}.source{font-size:13px;color:#65716c}.question{border-left:3px solid #cc8a54;padding:12px 16px;background:#faf5ee}.tags{color:#586965;font-size:14px}nav{display:flex;gap:12px;flex-wrap:wrap}pre{white-space:pre-wrap;word-break:break-word;font-size:12px}svg{width:100%;height:auto;font:13px system-ui}.lead{font-size:19px}.notice{background:#e6f0ed;padding:18px;border-radius:8px}@media(max-width:600px){main{padding:20px 12px}section{padding:16px}h1{font-size:27px}td,th{padding:8px}}@media print{body{background:white}main{padding:0}section{border:0;padding:8px 0;break-inside:auto}.scroll{overflow:visible}table{font-size:9px}th,td{padding:4px;min-width:0!important}a{color:inherit}details{display:block}details>pre{display:block}nav{display:none}}'''
doc='<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>微软｜AI Berkshire研究试验</title><style>'+css+'</style><main><header><p>AI BERKSHIRE / RESEARCH EXPERIMENT 01</p><p class="notice"><b>对比资格已撤销：</b>本版本混入用户SOP的九章结构与补充要求，属于混合流程产物。2026-11-15更正：不得作为AI Berkshire原生报告或两种方法的对比样本。原生重跑见独立交付。</p><h1>【混合流程版本】微软：AI增长很强，现金回报需要更多证据</h1><p class="tags">文档更新：2026-11-15 · 财报截止：FY2027 Q1 / 2026-09-30 · 行情截止：2026-11-13美股收盘</p><p class="lead">【我的推演】企业工作入口与云平台值得长期研究；按523.88美元，三年基准情景缺乏充分安全边际，AI投入的现金兑现是主要验证点。</p><p class="notice"><b>信息丰富度：A。</b>这是使用原仓库investment-research工作流与未修改工具完成的独立试验报告。仍有业务估值、部分独立交叉取证和资本回报等明确缺口，不作为“完整研究全部通过”。AI没有客户访谈、真实使用与内部成本数据，不将资料量等同投资确定性。</p><nav>'+''.join(f'<a href="#s{i}">{i}. {x}</a>' for i,x in enumerate(['业务','营收','财务','客户订单','竞争','行业','估值','治理','决策'],1))+'<a href="#review">试验与验收</a></nav></header>'+''.join(parts)+appendix+'</main></html>'
